import type { SchemaExtension } from "./blocks.ts";
import type { ColumnModel, FunctionModel, Model } from "./model.ts";
import type { TableModuleInfo } from "./tables.ts";

import { byCodePoint } from "../compare.ts";
import { functionGroups } from "./model.ts";
import {
  block,
  identifier,
  indent,
  nullable,
  pascal,
  prop,
  q,
  runtimeSubpath,
} from "./shared.ts";

export const GENERATED_HEADER =
  "// @generated by better-supabase gen. Do not edit; run `better-supabase gen` instead.";

function rowEntries(
  columns: readonly ColumnModel[],
  name: "app" | "db",
): string[] {
  return columns.map(
    (column) =>
      `${prop(column[name])}${column.selectable === false ? "?" : ""}: ${nullable(column.tsType, column.nullable)};`,
  );
}

function insertEntries(
  columns: readonly ColumnModel[],
  name: "app" | "db",
): string[] {
  return columns.map((column) => {
    if (!column.insertable) {
      return `${prop(column[name])}?: never;`;
    }

    const optional = column.optional ? "?" : "";

    return `${prop(column[name])}${optional}: ${nullable(column.tsType, column.nullable)};`;
  });
}

function updateEntries(
  columns: readonly ColumnModel[],
  name: "app" | "db",
): string[] {
  return columns.map((column) => {
    if (!column.updatable) {
      return `${prop(column[name])}?: never;`;
    }

    return `${prop(column[name])}?: ${nullable(column.tsType, column.nullable)};`;
  });
}

/**
 * Postgres passes `null` to any argument, so every argument accepts it. This
 * only widens what a caller may pass; no result type changes with it. An
 * optional argument also accepts `undefined`, which `rpc()` leaves out, so
 * `exactOptionalPropertyTypes` apps can pass a maybe-missing value.
 */
function argEntries(fn: FunctionModel): string[] {
  return fn.args.map(
    (arg) =>
      `${prop(arg.name)}${arg.optional ? "?" : ""}: ${nullable(arg.tsType, true)}${arg.optional ? " | undefined" : ""};`,
  );
}

function enrichedDatabase(model: Model): string[] {
  const schemas = model.config.schemas.flatMap((schema) => {
    const tables = model.tables
      .filter((t) => t.snapshot.schema === schema)
      .flatMap((table) => {
        const overrides = table.columns
          .filter(
            (column) =>
              (column.values !== undefined && !column.snapshot.isEnum) ||
              (column.json && column.tsType !== "Json") ||
              column.storage !== undefined,
          )
          .map((column) => `${prop(column.db)}: ${column.tsType};`);

        return overrides.length > 0
          ? block(prop(table.snapshot.name), overrides)
          : [];
      });

    return tables.length > 0 ? block(prop(schema), tables) : [];
  });

  if (schemas.length === 0) {
    return ["export type Database = SupabaseDatabase;"];
  }

  return [
    "export type Database = EnrichDatabase<",
    "  SupabaseDatabase,",
    "  {",
    ...indent(schemas, 2),
    "  }",
    ">;",
  ];
}

function modelsType(model: Model): string[] {
  const entries = model.tables.flatMap((table) => {
    const relations = table.relations.map(
      (relation) =>
        `${prop(relation.name)}: { table: ${q(relation.meta.table)}; kind: ${q(relation.meta.kind)}; nullable: ${String(relation.meta.nullable)} };`,
    );

    const pk = table.meta.primaryKey;

    const uniques = Object.entries(table.meta.uniqueKeys).map(
      ([name, columns]) =>
        `${prop(name)}: readonly [${columns.map(q).join(", ")}];`,
    );

    const flags: string[] = [];
    const tableFlags = table.meta.flags;

    if (tableFlags.softDelete) {
      flags.push(`softDelete: ${q(tableFlags.softDelete)};`);
    }

    if (tableFlags.timestamps) {
      flags.push("timestamps: true;");
    }

    if (tableFlags.tenant) {
      flags.push(`tenant: ${q(tableFlags.tenant)};`);
    }

    if (tableFlags.actor) {
      flags.push("actor: true;");
    }

    const none = "Record<never, never>";

    const union = (names: readonly string[]): string =>
      names.length === 0 ? "never" : names.map(q).join(" | ");

    return block(prop(table.key), [
      ...block("Row", rowEntries(table.columns, "app"), none),
      ...(table.snapshot.insertable
        ? block("Insert", insertEntries(table.columns, "app"), none)
        : ["Insert: never;"]),
      ...(table.snapshot.updatable
        ? block("Update", updateEntries(table.columns, "app"), none)
        : ["Update: never;"]),
      ...block("Relations", relations, none),
      `PrimaryKey: ${union(pk)};`,
      ...block("UniqueKeys", uniques, none),
      `Checks: ${union(table.snapshot.checks.map((check) => check.name))};`,
      `ForeignKeys: ${union(table.snapshot.foreignKeys.map((fk) => fk.name))};`,
      ...block("Flags", flags, none),
    ]);
  });

  return ["export type Models = {", ...indent(entries, 1), "};"];
}

function functionsType(model: Model): string[] {
  if (model.functions.length === 0) {
    return ["export type Functions = Record<never, never>;"];
  }

  const entries = [...functionGroups(model.functions)].flatMap(
    ([key, group]) => {
      const [first] = group;

      if (group.length === 1 && first) {
        return block(prop(key), [
          ...block("Args", argEntries(first), "Record<never, never>"),
          `Returns: ${first.returns};`,
        ]);
      }

      // An overload without arguments rejects every key, so it never
      // matches a call that names one.
      return [
        `${prop(key)}:`,
        ...indent(
          group.flatMap((fn, index) => {
            const lines = [
              ...block("Args", argEntries(fn), "Record<PropertyKey, never>"),
              `Returns: ${fn.returns};`,
            ];

            const end = index === group.length - 1 ? "};" : "}";

            return ["| {", ...indent(lines, 1), end];
          }),
          1,
        ),
      ];
    },
  );

  return ["export type Functions = {", ...indent(entries, 1), "};"];
}

export interface EmitOptions {
  /** Import path from the generated module to `better-supabase`. */
  readonly runtimeImport?: string;
  /** Import path from the generated module to `database.types.ts`. */
  readonly databaseTypesImport?: string;
  /**
   * The text of `database.types.ts`, written into the module instead of
   * imported. The content mapper serves one virtual file, which has no sibling
   * it could import.
   */
  readonly databaseTypes?: string;
  /**
   * Declares `meta` instead of importing it: a type-only module (the content
   * mapper's) never reads the metadata.
   */
  readonly declareMeta?: boolean;
  /** Import path for each JSON type import, keyed by the configured path. */
  readonly importPathFor: (from: string) => string;
  /** Import path from the generated module to the metadata module (`emitMeta`). */
  readonly metaImport?: string;
  /**
   * Writes the metadata into the module instead of importing it, so it is one
   * file.
   */
  readonly inlineMeta?: boolean;
  /** The installed blocks' repository extensions, which the schema carries. */
  readonly extensions?: readonly SchemaExtension[];
  /**
   * Import path to a generated module that exports `validators`; the schema
   * then installs `validation` with them, so writes are checked.
   */
  readonly validatorsImport?: string;
  /**
   * The per-table modules (`gen.tableModules`): the schema imports its tables
   * from them instead of from the metadata module, and the module adds
   * `clientSchema`.
   */
  readonly tables?: readonly TableModuleInfo[];
  /**
   * The server schema imports each table on first use (`gen.serverTables`
   * `lazy`). Function metadata is `generated.functions.js`.
   */
  readonly lazyServerTables?: boolean;
}

/**
 * The metadata module next to `generated.ts`: `generated.meta.js` and its
 * `.d.ts`.
 */
export function metaPaths(output: string): { js: string; dts: string } {
  const base = output.replace(/\.[cm]?[jt]sx?$/, "");

  return { js: `${base}.meta.js`, dts: `${base}.meta.d.ts` };
}

/**
 * JSON with one line per table, function and other named entry, so the module
 * stays small to load and a schema change still diffs per entry.
 */
function compactJson(meta: Readonly<Record<string, unknown>>): string {
  const entries = Object.entries(meta).map(([key, value]) => {
    const name = JSON.stringify(key);

    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      return `  ${name}: ${JSON.stringify(value)}`;
    }

    const inner = Object.entries(value).map(
      ([entry, item]) =>
        `    ${JSON.stringify(entry)}: ${JSON.stringify(item)}`,
    );

    return inner.length === 0
      ? `  ${name}: {}`
      : `  ${name}: {\n${inner.join(",\n")}\n  }`;
  });

  return `{\n${entries.join(",\n")}\n}`;
}

/** Function metadata as its own module, loaded on the first `rpc` call. */
export function emitFunctions(
  functions: Readonly<Record<string, unknown>>,
): string {
  return [
    GENERATED_HEADER,
    "/* oxlint-disable */",
    "/* eslint-disable */",
    "",
    `export default ${compactJson(functions)};`,
    "",
  ].join("\n");
}

/**
 * The schema metadata as plain JavaScript plus a one-line declaration, so
 * TypeScript reads `SchemaMeta` instead of checking thousands of lines of
 * object literal in every program that imports the generated module.
 */
export function emitMeta(
  model: Model,
  options: Pick<EmitOptions, "runtimeImport"> & {
    readonly types?: string;
    /** The tables live in `tables/<table>.ts`, so `tables` stays empty. */
    readonly splitTables?: boolean;
    /** Function metadata lives in `generated.functions.js`. */
    readonly splitFunctions?: boolean;
  } = {},
): { js: string; dts: string } {
  const runtime = options.runtimeImport ?? "better-supabase";

  const meta = {
    ...model.meta,
    ...(options.splitTables === true ? { tables: {} } : {}),
    ...(options.splitFunctions === true ? { functions: {} } : {}),
  };

  return {
    js: [
      GENERATED_HEADER,
      // Deno does not pick up a sibling .d.ts without this pragma.
      `// @ts-self-types="${options.types ?? "./generated.meta.d.ts"}"`,
      "/* oxlint-disable */",
      "/* eslint-disable */",
      "",
      `export default ${compactJson({ ...meta })};`,
      "",
    ].join("\n"),
    dts: [
      GENERATED_HEADER,
      "/* oxlint-disable */",
      "/* eslint-disable */",
      "",
      `import type { SchemaMeta } from ${q(runtime)};`,
      "",
      "declare const meta: SchemaMeta;",
      "export default meta;",
      "",
    ].join("\n"),
  };
}

/** Names the generated module declares or imports itself. */
const RESERVED_EXPORTS = [
  "defineSchema",
  "Schema",
  "SchemaMeta",
  "EnrichDatabase",
  "MutableWhere",
  "OrderByArg",
  "OrderByInput",
  "StoragePath",
  "SupabaseDatabase",
  "meta",
  "Json",
  "Database",
  "Models",
  "Functions",
  "TableName",
  "UniqueConstraint",
  "CheckConstraint",
  "ForeignKeyConstraint",
  "RowOf",
  "InsertOf",
  "UpdateOf",
  "WhereOf",
  "OrderByOf",
  "OrderTermOf",
  "WritableColumnOf",
  "GeneratedColumnOf",
  "buckets",
  "topics",
  "subjectTypes",
  "SubjectType",
  "RecordRef",
  "schema",
  "extensions",
  "Extensions",
  "ExtensionsOf",
  "validation",
  "validators",
];

/** An enum or a CHECK's value list: a constant and the union type of it. */
export interface ValueList {
  readonly constant: string;
  readonly typeName: string;
  readonly values: readonly string[];
  readonly source: string;
}

export function valueLists(model: Model): ValueList[] {
  const lists: ValueList[] = model.enums.map((entry) => ({
    constant: entry.constant,
    typeName: entry.typeName,
    values: entry.values,
    source: `enum ${entry.schema}.${entry.name}`,
  }));

  for (const table of model.tables) {
    for (const column of table.columns) {
      if (column.values && !column.snapshot.isEnum) {
        lists.push({
          constant: identifier(
            `${table.key}${pascal(column.app)}Values`.replace(/^[A-Z]/, (c) =>
              c.toLowerCase(),
            ),
          ),
          typeName: identifier(`${pascal(table.key)}${pascal(column.app)}`),
          values: column.values,
          source: `the CHECK on ${table.snapshot.schema}.${table.snapshot.name}.${column.db}`,
        });
      }
    }
  }

  return lists;
}

/** The repository extension calls the schema carries, in install order. */
function extensionCalls(
  options: EmitOptions,
): { readonly fn: string; readonly call: string }[] {
  return [
    ...(options.extensions ?? []).map((extension) => ({
      fn: extension.export,
      call: `${extension.export}(${extension.args})`,
    })),
    ...(options.validatorsImport === undefined
      ? []
      : [{ fn: "validation", call: "validation({ schemas: validators })" }]),
  ];
}

function runtimeImports(options: EmitOptions, runtime: string): string[] {
  const { validatorsImport } = options;

  return [
    ...(options.extensions ?? []).map(
      (extension) =>
        `import { ${extension.export} } from ${q(runtimeSubpath(runtime, extension.subpath))};`,
    ),
    ...(validatorsImport === undefined
      ? []
      : [`import { validators } from ${q(validatorsImport)};`]),
  ];
}

/**
 * `database.types.ts` inside a type-only namespace, so its `Json` and
 * `Database` don't clash with the module's own. Its `Constants` value is left
 * out: a namespace holding a value is not erasable syntax.
 */
function inlineDatabaseTypes(text: string): string[] {
  const constants = text.search(/^export const Constants\b/m);
  const types = (constants === -1 ? text : text.slice(0, constants)).trimEnd();

  return [
    "declare namespace SupabaseTypes {",
    ...indent([types], 1),
    "}",
    "type SupabaseDatabase = SupabaseTypes.Database;",
  ];
}

/** The imports of the per-table modules, and the `tables` object they fill. */
function tableImports(tables: readonly TableModuleInfo[]): string[] {
  return tables.map(
    (table) => `import { ${table.name} } from ${q(table.specifier)};`,
  );
}

function tablesObject(tables: readonly TableModuleInfo[]): string[] {
  return [
    "const tables = {",
    ...tables.map((table) => `  ${prop(table.key)}: ${table.name},`),
    "};",
  ];
}

/**
 * The schema of a client that registers the tables it uses
 * (`bsb.table(customers)`): no tables, functions or enums of its own, and the
 * same extensions.
 */
function clientSchemaLines(
  model: Model,
  typed: string | undefined,
  extensionsExpr: string | undefined,
): string[] {
  const claims = model.meta.claims
    ? `, claims: ${JSON.stringify(model.meta.claims)}`
    : "";

  const meta = `{ version: 1, casing: ${q(model.meta.casing)}, lazyTables: true, tables: {}, enums: {}, functions: {}${claims} }`;

  const extensions = extensionsExpr === undefined ? "" : `, ${extensionsExpr}`;

  return [
    "/**",
    " * The schema of a browser client without a table registry: it registers each",
    " * table module a page uses through `bsb.table(...)`.",
    " */",
    `export const clientSchema${typed === undefined ? "" : `: ${typed}`} = /*#__PURE__*/ defineSchema(${meta}${extensions});`,
  ];
}

/**
 * The runtime half of the generated module, for the content mapper: the values
 * (value lists, buckets, topics, extensions, subject types and `schema`), with
 * every type re-exported from the virtual module at `typesImport`, which holds
 * the full module.
 */
export function emitRuntime(
  model: Model,
  options: EmitOptions & { readonly typesImport: string },
): string {
  const runtime = options.runtimeImport ?? "better-supabase";
  const calls = extensionCalls(options);
  const subjects = Object.keys(model.config.subjects);

  const lines: string[] = [
    GENERATED_HEADER,
    "/* oxlint-disable */",
    "/* eslint-disable */",
    "",
    `import { defineSchema${options.validatorsImport === undefined ? "" : ", validation"} } from ${q(runtime)};`,
    ...runtimeImports(options, runtime),
    `import type { schema as typedSchema } from ${q(options.typesImport)};`,
    `import meta from ${q(options.metaImport ?? "./generated.meta.js")};`,
    "",
    `export type * from ${q(options.typesImport)};`,
    "",
    ...valueLists(model).map(
      (list) =>
        `export const ${list.constant} = [${list.values.map(q).join(", ")}] as const;`,
    ),
  ];

  if (model.meta.buckets) {
    lines.push(
      `export const buckets = ${JSON.stringify(model.meta.buckets, null, 2)} as const;`,
    );
  }

  if (model.meta.topics) {
    lines.push(
      `export const topics = ${JSON.stringify(model.meta.topics, null, 2)} as const;`,
    );
  }

  if (subjects.length > 0) {
    lines.push(
      `export const subjectTypes = [${subjects.map(q).join(", ")}] as const;`,
    );
  }

  lines.push(
    "",
    `export const schema: typeof typedSchema = defineSchema(meta${calls.length > 0 ? `, [${calls.map(({ call }) => call).join(", ")}]` : ""});`,
    "",
  );

  return lines.join("\n");
}

/** Renders the generated module. */
export function emitModule(model: Model, options: EmitOptions): string {
  const runtime = options.runtimeImport ?? "better-supabase";
  const extensions = options.extensions ?? [];
  const { validatorsImport } = options;
  const extended = extensions.length > 0 || validatorsImport !== undefined;

  const declaresMeta =
    options.inlineMeta === true || options.declareMeta === true;

  // The tables and the server's schema live in their own modules
  // (`emitSchemaModule`), so this one carries no table metadata.
  const split = options.tables !== undefined && !declaresMeta;

  const lines: string[] = [
    GENERATED_HEADER,
    "/* oxlint-disable */",
    "/* eslint-disable */",
    "",
    `import { defineSchema, ${validatorsImport === undefined ? "" : "validation, "}${extended ? "type ExtensionsOf, " : ""}type Schema${declaresMeta ? ", type SchemaMeta" : ""} } from ${q(runtime)};`,
    ...runtimeImports(options, runtime),
  ];

  const storagePaths = model.tables.some((table) =>
    table.columns.some((column) => column.storage !== undefined),
  );

  // Only an enriched Database names EnrichDatabase; an unused import fails
  // apps that set noUnusedLocals.
  const enriched = enrichedDatabase(model);

  lines.push(
    `import type { ${enriched.length > 1 ? "EnrichDatabase, " : ""}GeneratedColumns, MutableWhere, OrderByArg, OrderByInput${storagePaths ? ", StoragePath" : ""}, WritableColumns } from ${q(runtime)};`,
  );

  if (options.databaseTypes === undefined) {
    lines.push(
      `import type { Database as SupabaseDatabase } from ${q(options.databaseTypesImport ?? "./database.types.ts")};`,
    );
  }

  const byFile = new Map<string, string[]>();

  for (const entry of model.jsonImports) {
    const list = byFile.get(entry.from) ?? [];
    list.push(entry.name);
    byFile.set(entry.from, list);
  }

  for (const [from, names] of [...byFile.entries()].toSorted(([a], [b]) =>
    byCodePoint(a, b),
  )) {
    const valueNames = new Set(
      model.functions.flatMap((fn) =>
        fn.meta.returnsSchema === undefined ? [] : [fn.meta.returnsSchema],
      ),
    );

    const types = names.filter((name) => !valueNames.has(name));
    const values = names.filter((name) => valueNames.has(name));

    if (types.length > 0) {
      lines.push(
        `import type { ${types.toSorted().join(", ")} } from ${q(options.importPathFor(from))};`,
      );
    }

    if (values.length > 0) {
      lines.push(
        `import { ${values.toSorted().join(", ")} } from ${q(options.importPathFor(from))};`,
      );
    }
  }

  if (model.jsonImports.some((entry) => entry.value === true)) {
    lines.push(`import type { StandardSchemaV1 } from ${q(runtime)};`);
  }

  lines.push(
    options.inlineMeta
      ? `\nconst meta: SchemaMeta = ${compactJson({ ...model.meta })};`
      : options.declareMeta
        ? "\ndeclare const meta: SchemaMeta;"
        : split
          ? ""
          : `import meta from ${q(options.metaImport ?? "./generated.meta.js")};`,
    ...(options.databaseTypes === undefined
      ? []
      : ["", ...inlineDatabaseTypes(options.databaseTypes)]),
    "",
    "export type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[];",
    "",
    ...enriched,
    "",
  );

  const exported = new Map<string, string>(
    [
      ...RESERVED_EXPORTS,
      ...extensions.map((extension) => extension.export),
      ...model.jsonImports.map((entry) => entry.name),
    ].map((name) => [name, "the generated module"]),
  );

  const claim = (name: string, source: string): string => {
    const other = exported.get(name);

    if (other !== undefined) {
      throw new TypeError(
        `${source} and ${other} both export "${name}" from the generated module. Rename one of them in the database.`,
      );
    }

    exported.set(name, source);

    return name;
  };

  for (const list of valueLists(model)) {
    lines.push(
      `export const ${claim(list.constant, list.source)} = [${list.values.map(q).join(", ")}] as const;`,
      `export type ${claim(list.typeName, list.source)} = (typeof ${list.constant})[number];`,
    );
  }

  if (model.enums.length > 0) {
    lines.push("");
  }

  lines.push(
    ...modelsType(model),
    "",
    ...functionsType(model),
    "",
    "export type TableName = keyof Models;",
    "/** Constraint names for `isConflict`, `isCheck` and `isForeignKey`. */",
    "export type UniqueConstraint = { [T in TableName]: Extract<keyof Models[T]['UniqueKeys'], string> }[TableName];",
    "export type CheckConstraint = Models[TableName]['Checks'];",
    "export type ForeignKeyConstraint = Models[TableName]['ForeignKeys'];",
    "export type RowOf<T extends TableName> = Models[T]['Row'];",
    "export type InsertOf<T extends TableName> = Models[T]['Insert'];",
    "export type UpdateOf<T extends TableName> = Models[T]['Update'];",
    "/** A `where` for `T` you can assign to one key at a time. */",
    "export type WhereOf<T extends TableName> = MutableWhere<Models, T>;",
    "/** An `orderBy` for `T`: one sort or a list, by column or to-one relation. */",
    "export type OrderByOf<T extends TableName> = OrderByArg<Models, T>;",
    "/** One sort term of `T`'s `orderBy`, by column or to-one relation. */",
    "export type OrderTermOf<T extends TableName> = OrderByInput<Models, T>;",
    "/** Columns of `T` that `Insert` and `Update` accept. */",
    "export type WritableColumnOf<T extends TableName> = WritableColumns<Models, T>;",
    "/** Columns of `T` the database fills (generated columns): in `Row`, never writable. */",
    "export type GeneratedColumnOf<T extends TableName> = GeneratedColumns<Models, T>;",
    "",
  );

  if (model.meta.buckets) {
    lines.push(
      "/** Bucket configs for `defineBucket` from `better-supabase/storage`. */",
      `export const buckets = ${JSON.stringify(model.meta.buckets, null, 2)} as const;`,
      "",
    );
  }

  if (model.meta.topics) {
    lines.push(
      "/** Topic templates for `defineTopic` from `better-supabase/realtime`. */",
      `export const topics = ${JSON.stringify(model.meta.topics, null, 2)} as const;`,
      "",
    );
  }

  const subjects = Object.keys(model.config.subjects);

  const calls = extensionCalls(options);

  if (extended) {
    lines.push(
      "/** The installed blocks' repository extensions; `createSupabase` installs them. */",
      `${split ? "export " : ""}type Extensions = readonly [${calls.map(({ fn }) => `ReturnType<typeof ${fn}>`).join(", ")}];`,
      `${split ? "export " : ""}const extensions: Extensions = [${calls.map(({ call }) => (split ? `/*#__PURE__*/ ${call}` : call)).join(", ")}];`,
      "",
    );
  }

  const subjectType = subjects.length > 0 ? "SubjectType" : "string";

  const schemaType = extended
    ? `Schema<Models, Database, Functions, ${subjectType}, ExtensionsOf<Extensions>>`
    : `Schema<Models, Database, Functions${subjects.length > 0 ? ", SubjectType" : ""}>`;

  const schemaLine = `export const schema: ${schemaType} = defineSchema(meta${extended ? ", extensions" : ""});`;

  if (subjects.length > 0) {
    lines.push(
      "/** The app's subject types, from `config.subjects`. */",
      `export const subjectTypes = [${subjects.map(q).join(", ")}] as const;`,
      "export type SubjectType = (typeof subjectTypes)[number];",
      "/** One subject: its type and its id as text. */",
      "export type RecordRef<T extends SubjectType = SubjectType> = { readonly type: T; readonly id: string };",
      "",
    );
  }

  const tagged = model.functions.filter(
    (fn) => fn.meta.returnsSchema !== undefined,
  );

  if (tagged.length > 0) {
    lines.push(`import { registerRpcReturn } from ${q(runtime)};`);

    for (const fn of tagged) {
      lines.push(`registerRpcReturn(${q(fn.key)}, ${fn.meta.returnsSchema});`);
    }

    lines.push("");
  }

  if (split) {
    lines.push(
      ...clientSchemaLines(
        model,
        schemaType,
        extended ? "extensions" : undefined,
      ),
      "",
    );
  } else {
    lines.push(schemaLine, "");
  }

  return lines.join("\n");
}

/**
 * Where the server's schema module goes: `generated-schema.ts` beside
 * `generated.ts`. A `gen.file` named `schema.ts` would give `schema-schema.ts`,
 * so it gets `generated-schema.ts` too.
 */
export function schemaModulePath(output: string): string {
  const stem = output.replace(/\.[cm]?[jt]sx?$/, "");

  return /(?:^|\/)schema$/.test(stem)
    ? `${stem.slice(0, -"schema".length)}generated-schema.ts`
    : `${stem}-schema.ts`;
}

/**
 * The server's schema (`gen.tableModules`): every table module plus the
 * metadata module, in a module of its own so a client that imports
 * `generated.ts` never reaches it.
 */
export function emitSchemaModule(
  model: Model,
  tables: readonly TableModuleInfo[],
  options: EmitOptions & { readonly generated: string },
): string {
  const runtime = options.runtimeImport ?? "better-supabase";

  const extended =
    (options.extensions ?? []).length > 0 ||
    options.validatorsImport !== undefined;

  const subjects = Object.keys(model.config.subjects).length > 0;

  const types = [
    "Database",
    ...(extended ? ["Extensions"] : []),
    "Functions",
    "Models",
    ...(subjects ? ["SubjectType"] : []),
  ];

  const subjectType = subjects ? "SubjectType" : "string";

  const schemaType = extended
    ? `Schema<Models, Database, Functions, ${subjectType}, ExtensionsOf<Extensions>>`
    : `Schema<Models, Database, Functions${subjects ? ", SubjectType" : ""}>`;

  const header = [
    GENERATED_HEADER,
    "/* oxlint-disable */",
    "/* eslint-disable */",
    "",
    `import { defineSchema, type SchemaMeta, ${extended ? "type ExtensionsOf, " : ""}type Schema } from ${q(runtime)};`,
    `import meta from ${q(options.metaImport ?? "./generated.meta.js")};`,
    `import ${extended ? "{ extensions, " : "{ "}type ${types.join(", type ")} } from ${q(options.generated)};`,
  ];

  if (options.lazyServerTables === true) {
    const loaders = tables
      .map(
        (table) =>
          `  ${table.key}: () => import(${q(table.specifier)}).then((mod) => mod.${table.name}),`,
      )
      .join("\n");

    return [
      ...header,
      "",
      "const tableLoaders = {",
      loaders,
      "};",
      "",
      "/** The server's schema. Each table module loads on its first call, and function metadata loads on the first rpc call. */",
      `export const schema: ${schemaType} = /*#__PURE__*/ defineSchema({`,
      "  ...meta,",
      "  lazyTables: true,",
      "  tables: {},",
      "  functions: {},",
      "  tableLoaders,",
      `  loadFunctions: () => import(${q((options.metaImport ?? "./generated.meta.js").replace(/\.meta\.js$/, ".functions.js"))}).then((mod) => mod.default as SchemaMeta["functions"]),`,
      `}${extended ? ", extensions" : ""});`,
      "",
    ].join("\n");
  }

  return [
    ...header,
    ...tableImports(tables),
    "",
    ...tablesObject(tables),
    "",
    "/** The server's schema, with every table. Browser code imports `clientSchema` from the generated module instead. */",
    `export const schema: ${schemaType} = /*#__PURE__*/ defineSchema({ ...meta, tables }${extended ? ", extensions" : ""});`,
    "",
  ].join("\n");
}
